    /**
     * Doublons de contenu CROISES avec une famille EXTERIEURE (meme discipline D-041) -- a
     * completer si un futur balayage generique (scripts/check_combinatorial_duplicates.php)
     * en trouve. Voir docs/DECISIONS.md D-048.
     *
     * @var list<string>
     */
    private const EXTERNAL_DUPLICATE_KEYS = [];

    public function __construct(
        private readonly Connection $connection,
    ) {
    }

    public function build(int $length, string $letter1, string $letter2, string $letter3): AvecFourLettersLinks
    {
        $triple = [$letter1, $letter2, $letter3];
        sort($triple, SORT_STRING);
        [$x, $y, $z] = $triple;

        $statement = $this->connection->pdo()->prepare(
            "SELECT list_key, count FROM list_counts WHERE list_type = 'length_with_quad'"
            . ' AND (list_key LIKE ? OR list_key LIKE ? OR list_key LIKE ? OR list_key LIKE ?)'
        );
        $statement->execute([
            $length . ':%:' . $x . ':' . $y . ':' . $z,
            $length . ':' . $x . ':%:' . $y . ':' . $z,
            $length . ':' . $x . ':' . $y . ':%:' . $z,
            $length . ':' . $x . ':' . $y . ':' . $z . ':%',
        ]);

        self::$duplicateParentKeySet ??= array_flip(self::DUPLICATE_PARENT_KEYS);
        self::$siblingDuplicateKeySet ??= array_flip(self::SIBLING_DUPLICATE_KEYS);
        self::$externalDuplicateKeySet ??= array_flip(self::EXTERNAL_DUPLICATE_KEYS);

        $links = [];

        foreach ($statement as $row) {
            $key = (string) $row['list_key'];

            if (
                isset(self::$duplicateParentKeySet[$key])
                || isset(self::$siblingDuplicateKeySet[$key])
                || isset(self::$externalDuplicateKeySet[$key])
            ) {
                continue;
            }

            $parts = explode(':', $key, 5);
            $quad = [$parts[1], $parts[2], $parts[3], $parts[4]];

            $partner = null;
            foreach ($quad as $candidate) {
                if ($candidate !== $x && $candidate !== $y && $candidate !== $z) {
                    $partner = $candidate;
                    break;
                }
            }

            if ($partner === null) {
                // Defensif, jamais attendu : x/y/z toujours distincts (page palier 3 source),
                // donc exactement une des quatre lettres du quadruplet stocke n'est ni x, y, ni
                // z. Ignore silencieusement plutot que de produire un lien incorrect.
                continue;
            }

            $count = (int) $row['count'];
            $letters = [$x, $y, $z, $partner];
            sort($letters, SORT_STRING);
            $path = $length . '-lettres/avec/' . strtolower($letters[0]) . '/' . strtolower($letters[1]) . '/' . strtolower($letters[2]) . '/' . strtolower($letters[3]);
            $url = WordListFilters::fromPath($path)?->canonicalUrl();

            if ($url !== null) {
                $links[] = ['letter' => $partner, 'url' => $url, 'count' => $count];
            }
        }

        usort($links, static fn (array $a, array $b): int => $a['letter'] <=> $b['letter']);

        return new AvecFourLettersLinks(links: $links, queryCount: 1);
    }
